'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Symbol = require( '@stdlib/symbol/ctor' );
var isFloat64Array = require( '@stdlib/assert/is-float64array' );
var isInt32Array = require( '@stdlib/assert/is-int32array' );
var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;
var getPrototypeOf = require( '@stdlib/utils/get-prototype-of' );
var descriptor = require( '@stdlib/utils/property-descriptor' );


// VARIABLES //

var proto = getPrototypeOf( Float64Array.prototype );
var getLength = descriptor( proto, 'length' ).get;
var getBuffer = descriptor( proto, 'buffer' ).get;
var getByteOffset = descriptor( proto, 'byteOffset' ).get;
var getTag = Symbol.toStringTag && descriptor( proto, Symbol.toStringTag ).get;
var getBufferLength = descriptor( ArrayBuffer.prototype, 'byteLength' ).get;
var MAX = 9007199254740991;


// FUNCTIONS //

/**
* Adds safe integers without permitting an inexact indexed result.
* @private
* @param {integer} a - first integer
* @param {integer} b - second integer
* @throws {RangeError} inexact sum
* @returns {integer} sum
*/
function add( a, b ) {
	if ( (b > 0 && a > MAX-b) || (b < 0 && a < -MAX-b) ) {
		throw new RangeError( 'invalid argument. Indexed arithmetic must be exact.' );
	}
	return a+b;
}

/**
* Finds the greatest common divisor of positive safe integers.
* @private
* @param {PositiveInteger} a - first integer
* @param {PositiveInteger} b - second integer
* @returns {PositiveInteger} greatest common divisor
*/
function gcd( a, b ) {
	var r;
	while ( b !== 0 ) {
		r = a % b;
		a = b;
		b = r;
	}
	return a;
}

/**
* Checks an injective matrix view and captures its indexed-byte envelope.
* @private
* @param {TypedArray} data - typed view
* @param {NonNegativeInteger} N - dimension
* @param {integer} s1 - first stride
* @param {integer} s2 - second stride
* @param {integer} offset - offset
* @param {boolean} matrix - whether the view is a matrix
* @param {boolean} mutable - whether indexed writes are allowed
* @param {string} dtype - required intrinsic typed-array name
* @throws {TypeError} invalid buffer
* @throws {RangeError} invalid metadata or storage
* @returns {Array} buffer and half-open byte envelope
*/
function view( data, N, s1, s2, offset, matrix, mutable, dtype ) { // eslint-disable-line max-params
	var buffer;
	var bytes;
	var begin;
	var end;
	var lo;
	var hi;
	var a;
	var b;
	var g;
	if ( !( (dtype === 'Float64Array') ? isFloat64Array( data ) : isInt32Array( data ) ) || (getTag && getTag.call( data ) !== dtype) ) {
		throw new TypeError( 'invalid argument. Buffers must have the documented typed-array types.' );
	}
	buffer = getBuffer.call( data );

	// Intrinsic branding rejects shared storage, including cloned identities.
	getBufferLength.call( buffer );
	if ( !isSafeInteger( s1 ) || !isSafeInteger( s2 ) || !isSafeInteger( offset ) ) {
		throw new RangeError( 'invalid argument. Strides and offsets must be safe integers.' );
	}
	if ( N > 1 && ( (matrix && (s1 === 0 || s2 === 0)) || (mutable && !matrix && s1 === 0) ) ) {
		throw new RangeError( 'invalid argument. Mutable indexed views must be injective.' );
	}
	if ( matrix && N > 1 ) {
		g = gcd( (s1 < 0) ? -s1 : s1, (s2 < 0) ? -s2 : s2 );
		if ( ( ((s1 < 0) ? -s1 : s1)/g < N ) && ( ((s2 < 0) ? -s2 : s2)/g < N ) ) {
			throw new RangeError( 'invalid argument. Matrix indices must be injective.' );
		}
	}
	a = (N-1)*s1;
	b = ( matrix ) ? (N-1)*s2 : 0;
	if ( !isSafeInteger( a ) || !isSafeInteger( b ) ) {
		throw new RangeError( 'invalid argument. Indexed products must be exact.' );
	}
	lo = add( add( offset, (a < 0) ? a : 0 ), (b < 0) ? b : 0 );
	hi = add( add( offset, (a > 0) ? a : 0 ), (b > 0) ? b : 0 );
	if ( lo < 0 || hi >= getLength.call( data ) ) {
		throw new RangeError( 'invalid argument. Insufficient indexed storage.' );
	}
	bytes = ( dtype === 'Float64Array' ) ? 8 : 4;
	begin = lo*bytes;
	end = (hi+1)*bytes;
	if ( !isSafeInteger( begin ) || !isSafeInteger( end ) ) {
		throw new RangeError( 'invalid argument. Indexed byte envelope must be exact.' );
	}
	return [ buffer, add( getByteOffset.call( data ), begin ), add( getByteOffset.call( data ), end ) ];
}

/**
* Rejects overlapping indexed-byte envelopes.
* @private
* @param {Array} a - first envelope
* @param {Array} b - second envelope
* @throws {RangeError} overlap
* @returns {void}
*/
function disjoint( a, b ) {
	if ( a[0] === b[0] && a[1] < b[2] && b[1] < a[2] ) {
		throw new RangeError( 'invalid argument. Indexed A, E and IPIV envelopes must be disjoint.' );
	}
}


// MAIN //

/**
* Validates normalized active views and complete signed LAPACK pivots.
* @private
* @param {integer} u - triangle enum
* @param {integer} w - conversion enum
* @param {PositiveInteger} N - matrix order
* @param {Float64Array} A - matrix
* @param {integer} sa1 - row stride
* @param {integer} sa2 - column stride
* @param {integer} oa - matrix offset
* @param {Float64Array} E - off-diagonal storage
* @param {integer} se - storage stride
* @param {integer} oe - storage offset
* @param {Int32Array} P - signed one-based pivots
* @param {integer} sp - pivot stride
* @param {integer} op - pivot offset
* @throws {TypeError} invalid buffers
* @throws {RangeError} invalid metadata or pivots
* @returns {void}
*/
function validate( u, w, N, A, sa1, sa2, oa, E, se, oe, P, sp, op ) { // eslint-disable-line max-params
	var target;
	var step;
	var pair;
	var ae;
	var ee;
	var pe;
	var p;
	var i;
	var j;
	ae = view( A, N, sa1, sa2, oa, true, true, 'Float64Array' );
	ee = view( E, N, se, 0, oe, false, true, 'Float64Array' );
	pe = view( P, N, sp, 0, op, false, false, 'Int32Array' );
	disjoint( ae, ee );
	disjoint( ae, pe );
	disjoint( ee, pe );
	step = ( u === 121 ) ? -1 : 1;
	i = ( u === 121 ) ? N-1 : 0;
	while ( i >= 0 && i < N ) {
		p = P[ op+(i*sp) ];
		target = (p < 0) ? -p : p;
		if ( p === 0 || target > N || ( (u === 121) ? target > i+1 : target < i+1 ) ) {
			throw new RangeError( 'invalid argument. Invalid signed one-based pivot target.' );
		}
		if ( p < 0 ) {
			j = i+step;
			if ( j < 0 || j >= N ) {
				throw new RangeError( 'invalid argument. Incomplete two-by-two pivot block.' );
			}
			pair = P[ op+(j*sp) ];
			target = -pair;
			if ( pair >= 0 || target > N || ( (u === 121) ? target > i+1 : target < i+1 ) ) {
				throw new RangeError( 'invalid argument. Invalid two-by-two pivot block.' );
			}
			i = j;
		}
		i += step;
	}
}

module.exports = validate;
